def solution(k, ranges):
    answer = []

    arr = [(0, k)]
    i = 1
    while k > 1: # 콜라츠 추측
        if k % 2 == 0: k //= 2
        else: k = k * 3 + 1
        arr.append((i, k))
        i += 1
    
    sum_arr = []
    # 정적분 계산 -> 해당 문제에선 구간의 사다리꼴 넓이
    for i in range(len(arr)):
        if i == 0: sum_arr.append(0)
        else:
            tmp = (arr[i-1][1] + arr[i][1]) / 2
            sum_arr.append(tmp)
    
    # 구간합 계산
    for i in range(1, len(sum_arr)):
        sum_arr[i] += sum_arr[i-1]

    # 정해진 범위의 넓이를 구간합을 이용해 계산
    length = len(sum_arr) - 1
    for x1, x2 in ranges:
        x2 += length
        if x1 > x2: answer.append(-1)
        else: answer.append(sum_arr[x2]-sum_arr[x1])

    return answer

def solution(begin, target, words):
    # target이 words 목록에 없으면, 변환 실패
    if target not in set(words):
        return 0

    # 변환 가능할 경우,
    # 한 단어의 길이, 단어 리스트의 길이
    n, m = len(begin), len(words)
    # 변환하면서, 중복되면 손해니까 & 무한루프 방지?
    visited = [False] * m
    answer = []

    def dfs(word, cnt):
        # 아직 타겟도 아닌데 모든 단어를 거친 경우, 변환 실패
        if cnt > m:
            return 

        # 타겟으로 변환한 경우, 정답에 추가
        if word == target:
            answer.append(cnt)
            return

        for i in range(n):
            for j in range(m):
                # 방문한 적 없고, 현재 단어의 알파벳 하나만 빼고 같은 단어일 경우,
                if not visited[j] and word[:i] == words[j][:i] and word[i+1:] ==  words[j][i+1:]:
                    visited[j] = True
                    dfs(words[j], cnt+1)
                    visited[j] = False

    dfs(begin, 0)
    # 타겟을 찾았다면, 즉 변환 가능 했다면 최저 cnt 반환
    if answer:
        return min(answer)
    # 타겟을 못 찾았다면, 즉 변환 불가능하다면 0 return
    else:
        return 0

def solution(tickets):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for src, dst in sorted(tickets):
        graph[src].append(dst)

    route = []
    stack = ["ICN"]

    while stack:
        while graph[stack[-1]]:
            stack.append(graph[stack[-1]].pop())
        route.append(stack.pop())

    return route[::-1]

