def solution(X, Y):
    def find_common_digits(x, y, common):
        if not x or not y:
            return common
        if x[0] in y:
            common.append(x[0])
            y.remove(x[0])
        return find_common_digits(x[1:], y, common)

    common_digits = find_common_digits(list(X), list(Y), [])
    if not common_digits:
        return -1
    common_digits.sort()
    result = ''.join(common_digits)
    return int(result) if result != '0' * len(result) else 0

