def solution(gems):
    gem_num = len(set(gems))
    max_num = len(gems)
    basket = {gems[0]: 1}
    answer = [1, max_num]
    start, end = 0, 0
    while start < max_num and end < max_num:
        if len(basket) == gem_num:
            if answer[1] - answer[0] > end - start:
                answer = [start + 1, end + 1]
            basket[gems[start]] -= 1
            if basket[gems[start]] == 0:
                del basket[gems[start]]
            start += 1
        else:
            end += 1
            if end == max_num:
                break
            basket[gems[end]] = basket.get(gems[end], 0) + 1

    return answer

def solution(numbers, hand):
    answer = ''
    l = ['1', '4', '7', '*']
    m = ['2', '5', '8', '0']
    r = ['3', '6', '9', '#']

    cur_l = '*'
    cur_r = '#'

    # 거리 계산 함수 정의
    def calc_distance(num, cur, m, lr):
        num_idx = m.index(num)
        if cur in lr:
            cur_idx = lr.index(cur)
            return len(m[num_idx: cur_idx]) + 1 if num_idx < cur_idx else len(m[cur_idx: num_idx]) + 1
        else:
            cur_idx = m.index(cur)
            return len(m[num_idx: cur_idx]) if num_idx < cur_idx else len(m[cur_idx: num_idx])

    for n in numbers:
        s_n = str(n)
        if s_n in l:
            answer += 'L'
            cur_l = s_n
        elif s_n in r:
            answer += 'R'
            cur_r = s_n
        else:
            loc_l = calc_distance(s_n, cur_l, m, l)
            loc_r = calc_distance(s_n, cur_r, m, r)
            if loc_l == loc_r:
                if hand == 'left':
                    answer += 'L'
                    cur_l = s_n
                else:
                    answer += 'R'
                    cur_r = s_n
            elif loc_l < loc_r:
                answer += 'L'
                cur_l = s_n
            else:
                answer += 'R'
                cur_r = s_n

    return answer

