def solution(nodes, edges):
    def dfs(node, parent):
        count = [0, 0, 0, 0]
        for child in edges[node]:
            if child != parent:
                child_count = dfs(child, node)
                count[0] += child_count[0]
                count[1] += child_count[1]
                count[2] += child_count[2]
                count[3] += child_count[3]

        if node % 2 == 0:
            count[1] += 1
        else:
            count[0] += 1

        if len(edges[node]) % 2 == 0:
            count[3] += 1
        else:
            count[2] += 1

        return count

    edges_dict = {i: [] for i in range(nodes)}
    for u, v in edges:
        edges_dict[u].append(v)
        edges_dict[v].append(u)

    result = dfs(0, -1)
    return result[0], result[1], result[2], result[3]

def solution(n, k, cmd):
    answer = ['O'] * n
    table = { i:[i - 1, i + 1] for i in range(n) }
    table[0] = [None, 1]
    table[n - 1] = [n - 2, None]
    stack = []
    cur = k

    for c in cmd:
        if c == 'C':
            answer[cur] = 'X'
            prev, next = table[cur]
            stack.append([prev, cur, next])
            if next == None:
                cur = table[cur][0]
            else:
                cur = table[cur][1]
            if prev == None:
                table[next][0] = None
            elif next == None:
                table[prev][1] = None
            else:
                table[prev][1] = next
                table[next][0] = prev
        elif c == 'Z':
            prev, now, next = stack.pop()
            answer[now] = 'O'
            if prev == None:
                table[next][0] = now
            elif next == None:
                table[prev][1] = now
            else:
                table[next][0] = now
                table[prev][1] = now
        else:
            c1, c2 = c.split()
            c2 = int(c2)
            if c1 == 'D':
                for _ in range(c2):
                    cur = table[cur][1]
            else:
                for _ in range(c2):
                    cur = table[cur][0]

    return ''.join(answer)

