def solution(maps):
    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
    visited = [[0] * 5 for _ in range(5)]

    def dfs(x, y, distance):
        if x == 4 and y == 4:
            return distance
        visited[x][y] = 1
        min_distance = float('inf')
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < 5 and 0 <= ny < 5 and maps[nx][ny] == 1 and not visited[nx][ny]:
                result = dfs(nx, ny, distance + 1)
                if result != -1:
                    min_distance = min(min_distance, result)
        visited[x][y] = 0
        return min_distance if min_distance != float('inf') else -1

    return dfs(0, 0, 1)

def solution(n, wires):
    def dfs(node, visited, graph):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor, visited, graph)

    graph = {i: [] for i in range(1, n + 1)}
    for a, b in wires:
        graph[a].append(b)
        graph[b].append(a)

    min_diff = float('inf')
    for a, b in wires:
        graph[a].remove(b)
        graph[b].remove(a)

        visited = set()
        dfs(1, visited, graph)

        diff = abs((n - len(visited)) - len(visited))
        min_diff = min(min_diff, diff)

        graph[a].append(b)
        graph[b].append(a)

    return min_diff

