def solution(key, lock):
    def rotate(key):
        return [list(reversed(col)) for col in zip(*key)]

    def can_fit(key, lock, x_offset, y_offset):
        lock_size = len(lock)
        key_size = len(key)
        for i in range(key_size):
            for j in range(key_size):
                if 0 <= i + x_offset < lock_size and 0 <= j + y_offset < lock_size:
                    if lock[i + x_offset][j + y_offset] == 1 and key[i][j] == 1:
                        return False
                    if lock[i + x_offset][j + y_offset] == 0 and key[i][j] == 1:
                        lock[i + x_offset][j + y_offset] = 1
        for row in lock:
            if 0 in row:
                return False
        return True

    def unlock(key, lock, rotation):
        if rotation == 4:
            return False
        for x in range(len(lock) + len(key) - 1):
            for y in range(len(lock) + len(key) - 1):
                if can_fit(key, [row[:] for row in lock], x - len(key) + 1, y - len(key) + 1):
                    return True
        return unlock(rotate(key), lock, rotation + 1)

    return unlock(key, lock, 0)

