def solution(n, paths, gates, summits):
    from collections import defaultdict
    import sys

    graph = defaultdict(list)
    for u, v, w in paths:
        graph[u].append((v, w))
        graph[v].append((u, w))

    min_intensity = sys.maxsize
    best_summit = sys.maxsize

    def dfs(node, visited, intensity):
        nonlocal min_intensity, best_summit
        if node in visited:
            return
        visited.add(node)
        if node in summits:
            if intensity < min_intensity or (intensity == min_intensity and node < best_summit):
                min_intensity = intensity
                best_summit = node
            visited.remove(node)
            return
        for neighbor, weight in graph[node]:
            dfs(neighbor, visited, max(intensity, weight))
        visited.remove(node)

    for gate in gates:
        dfs(gate, set(), 0)

    return [best_summit, min_intensity]

