def solution(n, m, timetable):
    from heapq import heappop, heappush
    from collections import deque

    def distance(p1, p2):
        return max(abs(p1[0] - p2[0]), abs(p1[1] - p2[1]))

    def bfs(start, visited):
        queue = deque([start])
        distances = {start: 0}
        while queue:
            current = queue.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                neighbor = (current[0] + dx, current[1] + dy)
                if 0 <= neighbor[0] < n and 0 <= neighbor[1] < m and neighbor not in visited:
                    visited.add(neighbor)
                    distances[neighbor] = distances[current] + 1
                    queue.append(neighbor)
        return distances

    timetable.sort()
    customers = [(x, y) for x in range(n) for y in range(m)]
    visited = set()
    max_distance = 0

    for customer in timetable:
        if not visited:
            heappush(customers, customer)
            visited.add(customer)
            continue

        distances = bfs(customer, visited)
        for pos in distances:
            if pos not in visited:
                heappush(customers, pos)
                visited.add(pos)
                max_distance = max(max_distance, distances[pos])

    return max_distance

