def solution(rectangle, characterX, characterY, itemX, itemY):
    from collections import deque

    grid = [[0] * 10001 for _ in range(10001)]
    for x1, y1, x2, y2 in rectangle:
        for x in range(x1 * 2, x2 * 2):
            for y in range(y1 * 2, y2 * 2):
                grid[y][x] = 1

    for x1, y1, x2, y2 in rectangle:
        for x in range(x1 * 2, x2 * 2 + 1):
            grid[y1 * 2][x] = 2
            grid[y2 * 2][x] = 2
        for y in range(y1 * 2, y2 * 2 + 1):
            grid[y][x1 * 2] = 2
            grid[y][x2 * 2] = 2

    start = (characterX * 2, characterY * 2)
    end = (itemX * 2, itemY * 2)
    queue = deque([start])
    visited = set([start])
    distance = 0

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while queue:
        for _ in range(len(queue)):
            x, y = queue.popleft()
            if (x, y) == end:
                return distance // 2
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 10001 and 0 <= ny < 10001 and (nx, ny) not in visited and grid[ny][nx] == 2:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
        distance += 1

    return -1

