    def dfs(x, y, path_length):
        if x < 0 or x >= len(maps) or y < 0 or y >= len(maps[0]) or maps[x][y] == 1:
            return float('inf')
        if (x, y) == (len(maps) - 1, len(maps[0]) - 1):
            return path_length + 1

        maps[x][y] = 1
        min_path = min(
            dfs(x + 1, y, path_length + 1),
            dfs(x - 1, y, path_length + 1),
            dfs(x, y + 1, path_length + 1),
            dfs(x, y - 1, path_length + 1)
        )
        maps[x][y] = 0
        return min_path

    result = dfs(0, 0, 0)
    return result if result != float('inf') else -1

