        if idx2 >= len(lines):
            find_intersections(lines, idx1 + 1, idx1 + 2, intersections)
            return
        if idx2 < len(lines):
            a1, b1, c1 = lines[idx1]
            a2, b2, c2 = lines[idx2]
            det = a1 * b2 - a2 * b1
            if det != 0:
                x = (b1 * c2 - b2 * c1) // det
                y = (a2 * c1 - a1 * c2) // det
                if (b1 * c2 - b2 * c1) % det == 0 and (a2 * c1 - a1 * c2) % det == 0:
