def solution(depth, money):
    left, right = 1, max(depth)
    while left < right:
        mid = (left + right) // 2
        cost = sum((d * (d + 1) // 2) for d in depth if d >= mid)
        if cost <= money:
            left = mid + 1
        else:
            right = mid
    return left - 1

