    from bisect import bisect_right

    counts = Counter()
    for i in range(1, e + 1):
        counts[i] += 1

    sorted_counts = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    max_numbers = [num for num, _ in sorted_counts]

