def solution(game_board, table):
    from collections import deque

    def get_shapes(board):
        visited = [[False] * len(board[0]) for _ in range(len(board))]
        shapes = []

        def bfs(start):
            queue = deque([start])
            shape = []
            while queue:
                x, y = queue.popleft()
                shape.append((x - start[0], y - start[1]))
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < len(board) and 0 <= ny < len(board[0]) and not visited[nx][ny] and board[nx][ny] == 0:
                        visited[nx][ny] = True
                        queue.append((nx, ny))
            return shape

        for i in range(len(board)):
            for j in range(len(board[0])):
                if board[i][j] == 0 and not visited[i][j]:
                    visited[i][j] = True
                    shapes.append(bfs((i, j)))

        return shapes

    def rotate(shape):
        return [(y, -x) for x, y in shape]

    def flip(shape):
        return [(-x, y) for x, y in shape]

    def normalize(shape):
        min_x = min(x for x, y in shape)
        min_y = min(y for x, y in shape)
        return sorted((x - min_x, y - min_y) for x, y in shape)

    def generate_variants(shape):
        variants = set()
        current = shape
        for _ in range(4):
            current = rotate(current)
            variants.add(tuple(normalize(current)))
            variants.add(tuple(normalize(flip(current))))
        return variants

    game_shapes = get_shapes(game_board)
    table_shapes = get_shapes(table)

    table_variants = []
    for shape in table_shapes:
        table_variants.extend(generate_variants(shape))

    table_variants_count = {}
    for variant in table_variants:
        table_variants_count[variant] = table_variants_count.get(variant, 0) + 1

    answer = 0
    for shape in game_shapes:
        normalized_shape = normalize(shape)
        if tuple(normalized_shape) in table_variants_count and table_variants_count[tuple(normalized_shape)] > 0:
            answer += len(shape)
            table_variants_count[tuple(normalized_shape)] -= 1

    return answer

