        if pos == len(name):
            return 0
        up_down = min(ord(name[pos]) - ord('A'), ord('Z') - ord(name[pos]) + 1)
        return up_down + move_cursor(pos + 1, name)

    def find_min_moves(pos, name, left_moves, right_moves):
        if pos == len(name):
            return left_moves + right_moves
        left = find_min_moves(pos + 1, name, left_moves + 1, right_moves)
        right = find_min_moves(pos - 1 if pos > 0 else len(name) - 1, name, left_moves, right_moves + 1)
        return min(left, right)

    vertical_moves = move_cursor(0, name)
    horizontal_moves = find_min_moves(0, name, 0, 0)
    return vertical_moves + horizontal_moves

