def solution(n, lost, reserve):
    lost_set = set(lost) - set(reserve)
    reserve_set = set(reserve) - set(lost)

    def borrow_students(index):
        if index > n:
            return 0
        if index in lost_set:
            if index - 1 in reserve_set:
                reserve_set.remove(index - 1)
                lost_set.remove(index)
                return 1 + borrow_students(index + 1)
            elif index + 1 in reserve_set:
                reserve_set.remove(index + 1)
                lost_set.remove(index)
                return 1 + borrow_students(index + 1)
            else:
                return borrow_students(index + 1)
        else:
            return 1 + borrow_students(index + 1)

    return borrow_students(1) + (n - len(lost))

